/* Shared staff scheduling: all writes go to authenticated same-origin API routes. */
const byId=id=>document.getElementById(id);
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let signInReady=false;
byId('google-sign-in').onclick=event=>{if(!signInReady)event.preventDefault()};
let workspace,appointments=[],editing=null,seriesRequestKey=null,offset=0,busy=false,loadGeneration=0;
function message(text){byId('message').textContent=text;byId('message').hidden=!text}
async function api(path,options={}){
  const response=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(workspace?.csrf?{'X-CSRF-Token':workspace.csrf}:{}),...options.headers}});
  const data=await response.json().catch(()=>({error:'Staff scheduling is unavailable. Please try again.'}));
  if(response.status===401||response.status===403){workspace=null;appointments=[];loadGeneration++;byId('shared-agenda').replaceChildren();byId('time-off-list').replaceChildren();byId('working-days').replaceChildren();byId('shared-session-form').reset();byId('staff-app').hidden=true;byId('sign-in').hidden=false;byId('sign-out').hidden=true;if(byId('shared-session-dialog').open)byId('shared-session-dialog').close()}
  if(!response.ok)throw Error(data.error||'Could not complete this request.');return data;
}
function post(path,data){return api(path,{method:'POST',body:JSON.stringify(data)})}
function parts(value){const fields=new Intl.DateTimeFormat('en-CA',{timeZone:workspace.timezone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(value));const d=Object.fromEntries(fields.map(f=>[f.type,f.value]));return {date:`${d.year}-${d.month}-${d.day}`,time:`${d.hour}:${d.minute}`}}
function caseLabel(id){return workspace.cases.find(c=>c.id===id)?.label||'Case unavailable'}
function staffLabel(id){return workspace.clinicians.find(c=>c.id===id)?.name||id}
function paintAgenda(){const q=byId('session-search').value.trim().toLowerCase();const rows=appointments.filter(a=>`${a.title} ${caseLabel(a.case_id)} ${staffLabel(a.clinician_id)}`.toLowerCase().includes(q));byId('agenda-count').textContent=`Showing ${rows.length} matching sessions from ${appointments.length} loaded. Timezone: ${workspace.timezone}.`;
  byId('shared-agenda').innerHTML=rows.map(a=>{const start=parts(a.starts_at),end=parts(a.ends_at);return `<article class="session-row"><div class="session-time"><strong>${escapeHTML(start.date)}</strong><p>${escapeHTML(start.time)}–${escapeHTML(end.time)}</p></div><div><h3>${escapeHTML(a.title)}</h3><p>${escapeHTML(caseLabel(a.case_id))} · ${escapeHTML(a.location)}</p><p>${escapeHTML(staffLabel(a.clinician_id))}${a.series_id?' · Recurring session':''}</p></div><span class="status">${escapeHTML(a.status)}</span><button data-edit-session="${escapeHTML(a.id)}" aria-label="Edit ${escapeHTML(a.title)}">Edit session</button></article>`}).join('')||'<div class="empty"><h3>No sessions match.</h3><p>Adjust the filters or plan a session.</p></div>';
}
async function loadAgenda(append=false){if(!workspace)return;const generation=++loadGeneration;const from=byId('from-date').value,to=byId('to-date').value;if(!from||!to||from>to){message('Choose a valid date range.');return}
  const nextOffset=append?offset:0;const query=new URLSearchParams({from_date:from,to_date:to,status:byId('attendance-filter').value,limit:100,offset:nextOffset});
  try{const result=await api('/api/appointments?'+query);if(generation!==loadGeneration||!workspace)return;appointments=append?[...appointments,...result.items]:result.items;offset=nextOffset+result.items.length;byId('load-more').hidden=result.items.length<100;paintAgenda();message('')}catch(error){message(error.message)}
}
function clinicianOptions(caseId){return workspace.clinicians.filter(c=>workspace.assignments.some(a=>a.case_id===caseId&&a.clinician_id===c.id)).map(c=>`<option value="${escapeHTML(c.id)}">${escapeHTML(c.name)}</option>`).join('')}
function openSession(id){editing=appointments.find(a=>a.id===id)||null;seriesRequestKey=crypto.randomUUID();byId('shared-session-form').reset();byId('shared-session-error').hidden=true;byId('shared-case').innerHTML=workspace.cases.map(c=>`<option value="${escapeHTML(c.id)}">${escapeHTML(c.label)}</option>`).join('');byId('shared-case').value=editing?.case_id||workspace.cases[0]?.id||'';byId('shared-clinician').innerHTML=clinicianOptions(byId('shared-case').value);byId('shared-clinician').value=editing?.clinician_id||byId('shared-clinician').options[0]?.value||'';
  byId('shared-date').value=editing?parts(editing.starts_at).date:parts(new Date().toISOString()).date;byId('shared-time').value=editing?parts(editing.starts_at).time:'09:00';byId('shared-title').value=editing?.title||'';byId('shared-duration').value=editing?(Date.parse(editing.ends_at)-Date.parse(editing.starts_at))/60000:60;byId('shared-location').value=editing?.location||'Office';byId('shared-status').value=editing?.status||'Scheduled';byId('shared-cancel').hidden=!editing;byId('repeat-fields').hidden=!!editing;byId('shared-count').disabled=true;byId('edit-scope-label').hidden=!editing?.series_id;byId('shared-session-heading').textContent=editing?'Edit session':'Plan a session';applyScope();byId('shared-session-dialog').showModal();
}
function applyScope(){const future=!!editing?.series_id&&byId('edit-scope').value==='future';for(const id of ['shared-case','shared-clinician','shared-title','shared-date'])byId(id).disabled=future;byId('series-policy').hidden=!future;byId('shared-status').disabled=future;byId('shared-cancel').textContent=future?'Cancel this & future sessions':'Cancel session'}
byId('shared-case').onchange=()=>{byId('shared-clinician').innerHTML=clinicianOptions(byId('shared-case').value)};byId('shared-repeat').onchange=()=>{byId('shared-count').disabled=byId('shared-repeat').value==='0'};byId('edit-scope').onchange=applyScope;
byId('shared-session-form').onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;byId('shared-save').disabled=true;byId('shared-cancel').disabled=true;byId('shared-session-error').hidden=true;
  try{const d={case_id:byId('shared-case').value,clinician_id:byId('shared-clinician').value,title:byId('shared-title').value.trim(),date:byId('shared-date').value,time:byId('shared-time').value,duration:Number(byId('shared-duration').value),location:byId('shared-location').value,status:byId('shared-status').value};
    if(editing?.series_id&&byId('edit-scope').value==='future')await post('/api/series/future',d.status==='Cancelled'?{id:editing.id,version:editing.version,status:'Cancelled'}:{id:editing.id,version:editing.version,time:d.time,duration:d.duration,location:d.location});
    else if(!editing&&Number(byId('shared-repeat').value)){delete d.status;await post('/api/series',{...d,interval_weeks:Number(byId('shared-repeat').value),count:Number(byId('shared-count').value),request_key:seriesRequestKey})}
    else await post('/api/appointments',{...d,...(editing?{id:editing.id,version:editing.version}:{})});
    byId('shared-session-dialog').close();await loadAgenda();
  }catch(error){byId('shared-session-error').textContent=error.message;byId('shared-session-error').hidden=false}finally{busy=false;byId('shared-save').disabled=false;byId('shared-cancel').disabled=false}
};
byId('shared-cancel').onclick=()=>{byId('shared-status').value='Cancelled';byId('shared-session-form').requestSubmit()};byId('close-session').onclick=()=>byId('shared-session-dialog').close();byId('plan-session').onclick=()=>openSession();byId('shared-agenda').onclick=event=>{const b=event.target.closest('[data-edit-session]');if(b)openSession(b.dataset.editSession)};
for(const id of ['from-date','to-date','attendance-filter'])byId(id).onchange=()=>loadAgenda();byId('session-search').oninput=paintAgenda;byId('refresh').onclick=()=>loadAgenda();byId('load-more').onclick=()=>loadAgenda(true);
function toClock(minutes){return `${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`}
function paintAvailability(){const id=byId('availability-staff').value;const own=workspace.role==='clinician'&&workspace.user_id===id,canEdit=['administrator','supervisor'].includes(workspace.role)||own;const saved=workspace.availability.find(a=>a.clinician_id===id);byId('hours-state').textContent=saved?'Sessions must fit the saved working hours.':'Working hours have not been set. Scheduling remains unrestricted until hours are saved.';for(const input of byId('time-off-form').querySelectorAll('input'))input.disabled=!canEdit;byId('working-days').innerHTML=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map((label,day)=>{const window=saved?.windows.find(w=>w.day===day);const end=window?.end===1440?'23:59':toClock(window?.end||1020);return `<div class="working-day"><label><input data-working-day="${day}" type="checkbox" ${window?'checked':''} ${canEdit?'':'disabled'}>${label}</label><label>Start<input data-day-start="${day}" type="time" value="${window?toClock(window.start):'09:00'}" ${canEdit?'':'disabled'}></label><label>End<input data-day-end="${day}" type="time" value="${end}" ${canEdit?'':'disabled'}></label></div>`}).join('');byId('hours-form').querySelector('button').disabled=!canEdit;byId('time-off-form').querySelector('button').disabled=!canEdit;byId('time-off-list').innerHTML=workspace.time_off.filter(t=>t.clinician_id===id).map(t=>{const s=parts(t.starts_at),e=parts(t.ends_at);return `<div class="time-off-row"><span>${escapeHTML(s.date)} ${escapeHTML(s.time)} → ${escapeHTML(e.date)} ${escapeHTML(e.time)}</span>${canEdit?`<button data-remove-off="${escapeHTML(t.id)}">Remove</button>`:''}</div>`}).join('')||'<p class="muted">No time off recorded.</p>';byId('hours-error').hidden=true;byId('off-error').hidden=true}
async function refreshWorkspace(){workspace=await api('/api/bootstrap');paintAvailability()}
async function formAction(form,errorId,action){const button=form.querySelector('button');button.disabled=true;byId(errorId).hidden=true;try{await action();await refreshWorkspace();message('Availability updated.')}catch(error){byId(errorId).textContent=error.message;byId(errorId).hidden=false}finally{const id=byId('availability-staff').value;button.disabled=!workspace||!(['administrator','supervisor'].includes(workspace.role)||(workspace.role==='clinician'&&workspace.user_id===id))}}
byId('hours-form').onsubmit=event=>{event.preventDefault();formAction(event.target,'hours-error',async()=>{const minutes=value=>{const [h,m]=value.split(':').map(Number);return h*60+m};const windows=Array.from(document.querySelectorAll('[data-working-day]:checked')).map(input=>{const day=Number(input.dataset.workingDay);return {day,start:minutes(document.querySelector(`[data-day-start="${day}"]`).value),end:minutes(document.querySelector(`[data-day-end="${day}"]`).value)}});await post('/api/availability',{clinician_id:byId('availability-staff').value,windows})})};
byId('time-off-form').onsubmit=event=>{event.preventDefault();formAction(event.target,'off-error',()=>post('/api/time-off',{clinician_id:byId('availability-staff').value,from_date:byId('off-from-date').value,from_time:byId('off-from-time').value,to_date:byId('off-to-date').value,to_time:byId('off-to-time').value}))};
byId('time-off-list').onclick=async event=>{const b=event.target.closest('[data-remove-off]');if(!b)return;b.disabled=true;try{await api('/api/time-off/'+encodeURIComponent(b.dataset.removeOff),{method:'DELETE'});await refreshWorkspace()}catch(error){message(error.message);b.disabled=false}};byId('availability-staff').onchange=paintAvailability;
document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-current',b===button?'page':'false'));byId('schedule-panel').hidden=button.dataset.tab!=='schedule';byId('availability-panel').hidden=button.dataset.tab!=='availability';message('')});
byId('sign-out').onclick=async()=>{try{await post('/api/logout',{});location.reload()}catch(error){message(error.message)}};
async function start(){try{const status=await api('/auth/status');signInReady=status.ready;byId('google-sign-in').setAttribute('aria-disabled',String(!signInReady));if(!signInReady)message('Staff sign-in is being set up. Please try again later.');workspace=await api('/api/bootstrap');byId('sign-in').hidden=true;byId('staff-app').hidden=false;byId('sign-out').hidden=false;byId('identity').textContent=`${workspace.user_id} · ${workspace.role} · ${workspace.timezone}`;byId('availability-staff').innerHTML=workspace.clinicians.map(c=>`<option value="${escapeHTML(c.id)}">${escapeHTML(c.name)}</option>`).join('');paintAvailability();const day=parts(new Date().toISOString()).date;byId('from-date').value=day;const last=new Date(day+'T12:00:00Z');last.setUTCDate(last.getUTCDate()+180);byId('to-date').value=last.toISOString().slice(0,10);byId('plan-session').disabled=!workspace.cases.length;await loadAgenda()}catch(error){if(error.message!=='Sign in to continue')message(error.message)}}
start();setInterval(()=>{if(workspace&&offset<=100&&!document.hidden&&!byId('shared-session-dialog').open&&byId('availability-panel').hidden)loadAgenda()},30000);
